import{OCEAN_CONFIG as s}from"./config.min.js";export function escapeAction({begun:t,finished:e,paused:r}){return!t||e?null:r?"resume":"pause"}export function isEditable(t){if(!t)return!1;if(t.isContentEditable)return!0;const e=String(t.tagName||"").toLowerCase();if(e==="textarea"||e==="select")return!0;if(e!=="input")return!1;const r=String(t.type||"text").toLowerCase();return!["range","button","checkbox","radio","submit","reset"].includes(r)}export function seekTarget(t,e=s){const r=e.storm.seconds-e.controls.endGuardSeconds,n=Number(t);return Number.isFinite(n)?Math.min(r,Math.max(0,n)):0}export function keySeekTarget(t,e,r=s){const n=r.controls,o=Number.isFinite(e)?e:0;switch(t){case"ArrowRight":case"ArrowUp":return seekTarget(o+n.stepSeconds,r);case"ArrowLeft":case"ArrowDown":return seekTarget(o-n.stepSeconds,r);case"PageUp":return seekTarget(o+n.pageSeconds,r);case"PageDown":return seekTarget(o-n.pageSeconds,r);case"Home":return 0;case"End":return seekTarget(r.storm.seconds,r);default:return null}}export function clockLabel(t){const e=Math.max(0,Math.floor(Number(t)||0));return`${Math.floor(e/60)}:${String(e%60).padStart(2,"0")}`}export function valueText(t,e=s){const r=Math.max(0,Math.floor(Number(t)||0)),n=Math.round(e.storm.seconds);return`${r} ${r===1?"second":"seconds"} of ${n}`}export function progressPercent(t,e=s){return`${(Math.min(1,Math.max(0,(Number(t)||0)/e.storm.seconds))*100).toFixed(2)}%`}export function mayIdle({scrubbing:t,hovering:e,keyboardFocus:r}){return!t&&!e&&!r}export function lightningAllowed({scrubbing:t,holdSeconds:e}){return!t&&!(e>0)}
